
const rows=[['G001','农夫山泉杭州经销','饮料供应商','赵经理','0571-8888','杭州市余杭区','5','月结','30','李四','工商银行 6222****8888','6600','1000','正常'],['G002','康师傅食品','食品供应商','钱经理','0571-6666','杭州市萧山区','3','现结','0','李四','建设银行 6227****6666','12000','0','正常'],['G003','顺丰物流','物流服务商','陈经理','95338','杭州市拱墅区','1','月结','30','王五','招商银行 6214****1234','3200','0','正常']];
rows.forEach((r,i)=>tbody.insertAdjacentHTML('beforeend',`<tr><td><input type="checkbox" onchange="sel.textContent=document.querySelectorAll('tbody input:checked').length"></td><td>${i+1}</td>${r.map(x=>`<td>${x}</td>`).join('')}<td class="fix"><span class="link" onclick="openEdit('修改供应商')">编辑</span><span class="link">删除</span></td></tr>`));
function openEdit(title){mask.innerHTML=`<div class="modal edit"><div class="mh">${title}<span class="close" onclick="closeM()">×</span></div><div class="edit-tabs" id="editTabs"><span class="on" onclick="jumpSec('base')">基础信息</span><span onclick="jumpSec('settle')">结算设置</span><span onclick="jumpSec('accounts')">收款账户</span><span onclick="jumpSec('invoice')">发票信息</span><span onclick="jumpSec('contacts')">联系人</span><span onclick="jumpSec('import')">导入修改</span></div><div class="body" id="editBody" onscroll="syncTabs()"><section class="section" id="base"><div class="sec">基础信息</div><div class="form3"><label class="field">供应商编码<input disabled value="G001"></label><label class="field"><b>*</b> 供应商名称<input value="农夫山泉杭州经销"></label><label class="field">供应商类型<select><option>饮料供应商</option><option>食品供应商</option><option>物流服务商</option></select></label><label class="field">联系人<input value="赵经理"></label><label class="field">联系电话<input value="0571-8888"></label><label class="field">地址<input value="杭州市余杭区"></label><label class="field"><b>*</b> 到货天数<input value="5"></label><label class="field">默认采购员<select><option>李四</option></select></label><label class="field">状态<select><option>正常</option><option>停用</option></select></label></div></section><section class="section" id="settle"><div class="sec">结算设置</div><div class="form3"><label class="field">结算方式<select><option>月结</option><option>现结</option><option>预付</option></select></label><label class="field">账期天数<input value="30"></label><label class="field">付款条件<input value="到货后30天付款"></label><label class="field">应付余额<input disabled value="6600.00"></label><label class="field">预付余额<input disabled value="1000.00"></label><label class="field">费用余额<input disabled value="0.00"></label></div><div class="pay-preview">付款时可在付款单中选择本供应商的任一正常收款账户；默认带出“默认账户”。</div></section><section class="section" id="accounts"><div class="sec">供应商收款账户</div>${accountCard('默认账户','工商银行','6222 8888 9999 0000','农夫山泉杭州经销有限公司','是')}${accountCard('备用账户','建设银行','6227 6666 8888 0000','农夫山泉杭州经销有限公司','否')}<button class="btn primary" onclick="toast('已新增账户行')">新增账户</button><table class="matrix"><tr><th>账户名称</th><th>开户行</th><th>银行账号</th><th>收款户名</th><th>是否默认</th><th>状态</th><th>操作</th></tr><tr><td>默认账户</td><td>工商银行</td><td>6222****0000</td><td>农夫山泉杭州经销有限公司</td><td>是</td><td>正常</td><td>设为默认 删除</td></tr><tr><td>备用账户</td><td>建设银行</td><td>6227****0000</td><td>农夫山泉杭州经销有限公司</td><td>否</td><td>正常</td><td>设为默认 删除</td></tr></table></section><section class="section" id="invoice"><div class="sec">发票信息</div><div class="form3"><label class="field">发票抬头<input value="农夫山泉杭州经销有限公司"></label><label class="field">税号<input value="9133********"></label><label class="field">开户行<input value="工商银行"></label><label class="field">银行账号<input value="6222****0000"></label><label class="field">开票地址<input value="杭州市余杭区"></label><label class="field">开票电话<input value="0571-8888"></label></div></section><section class="section" id="contacts"><div class="sec">联系人</div><table class="matrix"><tr><th>姓名</th><th>职务</th><th>手机</th><th>邮箱</th><th>默认</th></tr><tr><td>赵经理</td><td>销售经理</td><td>138****2222</td><td>zhao@example.com</td><td>是</td></tr></table></section><section class="section" id="import"><div class="sec">导入修改/批量修改</div><div class="form3"><label class="field">导入匹配字段<select><option>供应商编码</option><option>供应商名称</option></select></label><label class="field">允许批量改账期<select><option>是</option></select></label><label class="field">允许批量改账户<select><option>是</option></select></label></div></section></div><div class="bottom"><button class="btn primary" onclick="toast('已保存供应商')">保存并继续</button><button class="btn">复制新增</button><button class="btn" onclick="closeM();toast('保存并退出')">保存并退出</button><button class="btn" onclick="closeM()">取消</button></div></div>`;mask.classList.add('show')}
function accountCard(name,bank,no,owner,def){return `<div class="account-card"><div class="account-head">${name} <span class="badge ${def==='是'?'ok':'wait'}">${def==='是'?'默认':'备用'}</span></div><div class="account-grid"><label>账户名称<input value="${name}"></label><label>开户行<input value="${bank}"></label><label>银行账号<input value="${no}"></label><label>收款户名<input value="${owner}"></label><label>是否默认<select><option>${def}</option><option>${def==='是'?'否':'是'}</option></select></label><label>状态<select><option>正常</option><option>停用</option></select></label></div></div>`}
function jumpSec(id){document.getElementById(id).scrollIntoView({block:'start',behavior:'smooth'});setTimeout(syncTabs,260)}
const secIds=['base','settle','accounts','invoice','contacts','import'];function syncTabs(){let body=document.getElementById('editBody');if(!body)return;let active=0;secIds.forEach((id,i)=>{let el=document.getElementById(id);if(el&&el.offsetTop-body.scrollTop<170)active=i});document.querySelectorAll('#editTabs span').forEach((x,i)=>x.classList.toggle('on',i===active))}
function closeM(){mask.classList.remove('show')}function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.tt);window.tt=setTimeout(()=>t.classList.remove('show'),2200)}
